// probe-r3-1-git-fd3-daemon-leak.mjs
// Tests Question 1 & B3 (§6.1, §6.4): Passing main.lock description at stdio[3]
// to git commit clears FD_CLOEXEC on fd 3. Any detached daemon spawned by git
// (e.g. git gc --auto --detach, gpg-agent, fsmonitor--daemon) or by a hook
// inherits fd 3 and holds the kernel flock indefinitely after git commit and
// the Node parent close their fds and exit.
import fs from "node:fs";
import path from "node:path";
import { spawn, spawnSync, execFileSync } from "node:child_process";

const work = fs.mkdtempSync(path.join("/tmp/fgos-redteam-v3-suite-ZSpt4u", "r3-1-"));
const lockFile = path.join(work, "main.lock");
fs.writeFileSync(lockFile, "");

function lockFd(fd) {
  return spawnSync("flock", ["-n", "3"], { stdio: ["ignore", "ignore", "pipe", fd] }).status === 0;
}
function strangerCanLock(file) {
  return spawnSync("flock", ["-n", file, "true"]).status === 0;
}

const repo = path.join(work, "repo");
execFileSync("git", ["init", "-q", repo]);
execFileSync("git", ["-C", repo, "config", "user.email", "probe@example.com"]);
execFileSync("git", ["-C", repo, "config", "user.name", "probe"]);
fs.writeFileSync(path.join(repo, "a.txt"), "hello");
execFileSync("git", ["-C", repo, "add", "a.txt"]);

// Real git pre-commit hook (exact borrow check from v3 §6.4) + post-commit / gc daemon simulation
const preCommit = path.join(repo, ".git", "hooks", "pre-commit");
fs.writeFileSync(preCommit, `#!/bin/sh
devino=\$(stat -L -c %d:%i /proc/self/fd/3 2>/dev/null)
if [ "\$devino" = "\$EXPECT_DEVINO" ] && flock -n 3; then
  echo borrower > "\$PROBE_OUT/hook-verdict"
else
  echo refused > "\$PROBE_OUT/hook-verdict"
  exit 1
fi
`, { mode: 0o755 });

// Simulate a background daemon spawned by git commit (like git gc --auto / gpg-agent / fsmonitor)
// which git spawns without closing fd 3 because git does not know fd 3 exists.
const postCommit = path.join(repo, ".git", "hooks", "post-commit");
fs.writeFileSync(postCommit, `#!/bin/sh
setsid sleep 30 >/dev/null 2>&1 &
echo \$! > "\$PROBE_OUT/daemon.pid"
`, { mode: 0o755 });

const fd = fs.openSync(lockFile, "r+");
const acquired = lockFd(fd);
const st = fs.fstatSync(fd);
const gitRes = spawnSync("git", ["-C", repo, "commit", "-q", "-m", "test"], {
  stdio: ["ignore", "ignore", "pipe", fd],
  env: { ...process.env, FGOS_LOCK_FD: "main:3", EXPECT_DEVINO: `${st.dev}:${st.ino}`, PROBE_OUT: work },
});
// Node owner now closes its fd to release main.lock after git commit returned 0:
fs.closeSync(fd);

const daemonPid = Number(fs.readFileSync(path.join(work, "daemon.pid"), "utf8").trim());
const fd3TargetInDaemon = fs.readlinkSync(`/proc/${daemonPid}/fd/3`);
const fdInfo3InDaemon = fs.readFileSync(`/proc/${daemonPid}/fdinfo/3`, "utf8");
const canLockWhileDaemonAlive = strangerCanLock(lockFile);

process.kill(daemonPid, "SIGKILL");
for (let i = 0; i < 50; i++) {
  if (strangerCanLock(lockFile)) break;
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
}
const canLockAfterDaemonKilled = strangerCanLock(lockFile);

const out = {
  probe: "R3-1: git commit fd 3 borrow leaks kernel flock to detached child daemon",
  ownerAcquired: acquired,
  gitExitCode: gitRes.status,
  hookVerdict: fs.readFileSync(path.join(work, "hook-verdict"), "utf8").trim(),
  ownerClosedFd: true,
  daemonPid,
  daemonInheritedFd3Target: fd3TargetInDaemon,
  daemonFdInfoHasKernelLock: fdInfo3InDaemon.includes("lock:"),
  strangerCanLockAfterOwnerClosedFdAndGitExited: canLockWhileDaemonAlive,
  strangerCanLockAfterDaemonKilled: canLockAfterDaemonKilled,
};
console.log(JSON.stringify(out));

import fs from "node:fs";
