const storeMod = await import(path.join(REPO, "src/state/store.mjs"));
const claimPortMod = await import(path.join(REPO, "src/runner/claim-port.mjs"));

const execCallsUnderEventsLock = [];
const origExecFileSync = child_process.execFileSync;
let strictGuardEnabled = false;

child_process.execFileSync = function patchedExecFileSync(file, args, options) {
  const lockExists = fs.existsSync(path.join(fgosDir, "events.lock"));
  if (lockExists) {
    const stack = new Error().stack.split("\n").slice(1, 7).map((s) => s.trim());
    execCallsUnderEventsLock.push({
      cmd: [file, ...(args || [])].join(" "),
      stack,
    });
    if (strictGuardEnabled) {
      throw new Error("exec-under-hot-lock: " + [file, ...(args || [])].join(" "));
    }
  }
  return origExecFileSync.call(this, file, args, options);
};
syncBuiltinESMExports();

