const claimAndSettleExecCount = execCallsUnderEventsLock.length;

// 2. Observe moveWork(delivered) for heavy work with branch fgw/tsk-r32 + plan.md
storeMod.moveWork(fgosDir, { id: "tsk-r32", to: "awaiting-approval" });
storeMod.moveWork(fgosDir, { id: "tsk-r32", to: "delivered" });
const totalExecCount = execCallsUnderEventsLock.length;

// 3. Test §6.6 strict guard ("exec-under-hot-lock"):
// (a) claimWork crashes on currentHead(repoRoot)
// (b) assertPlanEvidence in moveWork(delivered) SWALLOWS the exec-under-hot-lock error inside try/catch
//     and falsely rejects a valid heavy item whose plan.md is on branch fgw/tsk-r32c!
storeMod.addWork(fgosDir, {
  id: "tsk-r32b",
  title: "Second task in todo",
  kind: "task",
  status: "todo",
  workflowStep: "executing",
  risk: "light",
  verify: "true",
