storeMod.addWork(fgosDir, {
  id: "tsk-r32c",
  title: "Third heavy task with plan on branch",
  kind: "task",
  status: "awaiting-approval",
  workflowStep: "executing",
  risk: "heavy",
  verify: "true",
  deps: [],
  refs: ["docs/specs/runner.md"],
