strictGuardEnabled = true;
let claimCrashedWithGuard = null;
try {
  claimPortMod.claimWork(fgosDir, {
    id: "tsk-r32b",
    actor: "session",
    isolate: false,
    repoRoot: repoDir,
  });
} catch (err) {
