}

let moveHeavyCrashedWithGuard = null;
try {
  storeMod.moveWork(fgosDir, { id: "tsk-r32c", to: "delivered" });
} catch (err) {
  moveHeavyCrashedWithGuard = err.message;
}

fs.rmSync(tmpRoot, { recursive: true, force: true });
console.log(JSON.stringify({
  probe: "R3-2: production withEventsLock executes 8 git subprocesses inside critical section; §6.6 exec-under-hot-lock guard crashes claimWork and is swallowed by try/catch in getMainFgosDir and assertPlanEvidence",
  claimIdBeforeGuard: claimRes.claimId,
  settleCompletedBeforeGuard: Boolean(settleRes),
  execSubprocessCountDuringClaimAndSettle: claimAndSettleExecCount,
  totalExecSubprocessCountUnderEventsLock: totalExecCount,
  observedExecCallsUnderEventsLock: execCallsUnderEventsLock,
  claimCrashedWhenGuardEnabled: claimCrashedWithGuard,
  moveHeavyFalsePreconditionFailureWhenGuardSwallowedByTryCatch: moveHeavyCrashedWithGuard,
}, null, 2));

// probe-r3-3-zombie-holder-hot-lock.mjs
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { judgeOwner, startTimeOf, currentBoot } from "./v3-bundle/era-ledger.mjs";
process.argv[2] = "library-import";
const { hotTryAcquire } = await import("./v3-bundle/probe-hot-reclaim.mjs");
import { resolveHolderLiveness } from "/home/vantt/projects/forgentX/src/runner/dispatch/process-identity.mjs";

const work = fs.mkdtempSync(path.join("/tmp/fgos-redteam-v3-suite-ZSpt4u", "r3-3-"));
const lockPath = path.join(work, "events.lock");

// Use python to fork a child that writes events.lock, gets SIGKILLed, and stays
// un-waited (zombie "Z") while we test judgeOwner, resolveHolderLiveness, and hotTryAcquire.
const py = `
import os, signal, time, json, subprocess, sys
lock_path = sys.argv[1]
boot_id = open("/proc/sys/kernel/random/boot_id").read().strip().replace("-", "")
pid = os.fork()
if pid == 0:
    st = open(f"/proc/{os.getpid()}/stat").read().rsplit(")", 1)[1].split()[19]
    with open(lock_path, "w") as f:
        json.dump({"pid": os.getpid(), "startTime": st, "boot": boot_id, "processStartTime": st, "bootId": open("/proc/sys/kernel/random/boot_id").read().strip()}, f)
    time.sleep(60)
time.sleep(0.1)
os.kill(pid, signal.SIGKILL)
# Wait until child is in Z (zombie) state, WITHOUT calling waitpid!
for _ in range(100):
    st_line = open(f"/proc/{pid}/stat").read()
    state = st_line.rsplit(")", 1)[1].split()[0]
    if state == "Z":
        break
    time.sleep(0.01)
open(lock_path + ".zombie-ready", "w").write(str(pid))
while not os.path.exists(lock_path + ".done"):
    time.sleep(0.02)
os.waitpid(pid, 0)
`;

const holderParent = (await import("node:child_process")).spawn("python3", ["-c", py, lockPath]);
while (!fs.existsSync(lockPath + ".zombie-ready")) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
}
const zombiePid = Number(fs.readFileSync(lockPath + ".zombie-ready", "utf8"));
const procStatState = fs.readFileSync(`/proc/${zombiePid}/stat`, "utf8").split(") ")[1].split(" ")[0];
const rec = JSON.parse(fs.readFileSync(lockPath, "utf8"));
let kill0Alive = false;
try { process.kill(zombiePid, 0); kill0Alive = true; } catch {}

const v3JudgeVerdict = judgeOwner(rec);
const prodResolveVerdict = resolveHolderLiveness(rec, kill0Alive);
const hotAcquireResultWhileZombie = hotTryAcquire(lockPath, { reclaimLock: true });

fs.writeFileSync(lockPath + ".done", "");
await new Promise((r) => holderParent.on("exit", r));
const hotAcquireResultAfterReap = hotTryAcquire(lockPath, { reclaimLock: true });

// Also check corrupt record (missing pid) in production resolveHolderLiveness:
const corruptRecordVerdictInProd = resolveHolderLiveness({}, false);

console.log(JSON.stringify({
  probe: "R3-3: Zombie process (state Z) misjudged as alive/held by §5.1 process-facts and hotTryAcquire",
  zombiePid,
  procStatState,
  kill0Alive,
  v3JudgeOwnerVerdict: v3JudgeVerdict,
  prodResolveHolderLivenessVerdict: prodResolveVerdict,
  hotTryAcquireWhileHolderIsZombie: hotAcquireResultWhileZombie,
  hotTryAcquireAfterParentWaitpid: hotAcquireResultAfterReap,
  prodResolveHolderLivenessOnCorruptRecordWithoutPid: corruptRecordVerdictInProd,
}));

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";

const REPO = "/home/vantt/projects/forgentX";
const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "r3-4-"));

// Part A: run.mjs:345-351 swallows EISDIR on tombstone directory and fails OPEN on resume
const fgosDir = path.join(tmpRoot, "main-repo", ".fgos");
fs.mkdirSync(fgosDir, { recursive: true });
const runMod = await import(path.join(REPO, "src/runner/main-checkout-lock.mjs"));
const worktreeCwd = path.join(tmpRoot, "wt-1");
fs.mkdirSync(worktreeCwd, { recursive: true });
const tombstoneLockPath = path.join(fgosDir, runMod.dispatchLockFile(worktreeCwd));
fs.mkdirSync(tombstoneLockPath, { recursive: true });
fs.writeFileSync(path.join(tombstoneLockPath, "MOVED-TO-V3"), "moved\n");

// Replicate exact guard from src/runner/execution/run.mjs:345-359
let holder;
let caughtCode = null;
try {
  holder = JSON.parse(fs.readFileSync(tombstoneLockPath, "utf8"))?.pid;
} catch (err) {
  caughtCode = err.code;
  holder = undefined;
}
const runMjsResumeGuardThrows = Boolean(holder && Number.isInteger(holder));
const runMjsResumeFailsOpen = !runMjsResumeGuardThrows;

// Part B: Quiescence scan (/proc/*/cmdline and /proc/*/cwd matching main checkout root)
// misses worker running inside a linked worktree outside main checkout root
const mainRoot = path.join(tmpRoot, "main-checkout");
const externalWorktree = path.join(tmpRoot, "external-linked-worktree");
const fakeReleaseEntry = path.join(tmpRoot, "release-store", "fgos-worker.mjs");
fs.mkdirSync(mainRoot, { recursive: true });
fs.mkdirSync(externalWorktree, { recursive: true });
fs.mkdirSync(path.dirname(fakeReleaseEntry), { recursive: true });
fs.writeFileSync(fakeReleaseEntry, "setInterval(() => {}, 1000);\n");

const worker = spawn(process.execPath, [fakeReleaseEntry, "--worktree", externalWorktree], {
  cwd: externalWorktree,
  stdio: "ignore",
});

await new Promise((r) => setTimeout(r, 80));

const cmdlineBuf = fs.readFileSync(`/proc/${worker.pid}/cmdline`);
const cmdlineStr = cmdlineBuf.toString("utf8").replace(/\0/g, " ");
const cwdTarget = fs.readlinkSync(`/proc/${worker.pid}/cwd`);
const detectedByMainRootQuiescenceScan =
  cmdlineStr.includes(mainRoot) || cwdTarget === mainRoot || cwdTarget.startsWith(mainRoot + "/");

worker.kill("SIGKILL");

// Part C: Per-cwd lazy tombstone + symlink vs realpath key mismatch (§6.8 step 4)
const realWt = path.join(tmpRoot, "real-wt");
const symlinkWt = path.join(tmpRoot, "symlink-wt");
fs.mkdirSync(realWt, { recursive: true });
fs.symlinkSync(realWt, symlinkWt);

const v1LockPathViaSymlink = path.join(fgosDir, runMod.dispatchLockFile(symlinkWt));
const v1LockPathViaRealpath = path.join(fgosDir, runMod.dispatchLockFile(fs.realpathSync(symlinkWt)));
const symlinkVsRealpathDiverges = v1LockPathViaSymlink !== v1LockPathViaRealpath;

// Part D: porting-store.mjs uses .fgos/porting/events.lock (not in §6.8 tombstone list)
const portingDir = path.join(fgosDir, "porting");
fs.mkdirSync(portingDir, { recursive: true });
const portingLockPath = path.join(portingDir, "events.lock");
const v3TombstonePaths = [
  path.join(fgosDir, "events.lock"),
  path.join(fgosDir, "claims.lock"),
  path.join(fgosDir, "main-checkout.lock"),
  path.join(fgosDir, "runtime/locks/dispatch-cwd.cutover"),
];
const portingLockCoveredByTombstones = v3TombstonePaths.includes(portingLockPath);

fs.rmSync(tmpRoot, { recursive: true, force: true });

console.log(JSON.stringify({
  probe: "R3-4: Cutover tombstone & quiescence holes (§6.8)",
  hole4a_runMjsResumeReadFileCode: caughtCode,
  hole4a_runMjsResumeFailsOpenOnTombstoneDir: runMjsResumeFailsOpen,
  hole4b_linkedWorktreeWorkerPid: worker.pid,
  hole4b_workerCwd: cwdTarget,
  hole4b_detectedByMainCheckoutQuiescenceScan: detectedByMainRootQuiescenceScan,
  hole4c_v1LockPathViaSymlink: path.basename(v1LockPathViaSymlink),
  hole4c_v1LockPathViaRealpath: path.basename(v1LockPathViaRealpath),
  hole4c_symlinkVsRealpathTombstoneDiverges: symlinkVsRealpathDiverges,
  hole4d_portingEventsLockCoveredByTombstones: portingLockCoveredByTombstones,
}, null, 2));

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, execFileSync } from "node:child_process";
import { acquireRunControl, buildRunControlHolder } from "/home/vantt/projects/forgentX/src/runner/dispatch/run-lock.mjs";

const suiteDir = "/tmp/fgos-redteam-v3-suite-ZSpt4u";
const v3BundleDir = path.join(suiteDir, "v3-bundle");
const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "r3-5-"));

// Sub-probe 5A: Partial post-receipt crash (supervisor dies after p4-settle.mjs writes result.json,
// before release / finalize-home runs). Verify p4-adopt.mjs returns "already-settled" and NEVER cleans home!
const attempt5A = path.join(tmpRoot, "attempt-5A");
fs.mkdirSync(path.join(attempt5A, "home"), { recursive: true });
fs.mkdirSync(path.join(attempt5A, "outbox"), { recursive: true });
fs.writeFileSync(path.join(attempt5A, "attempt.lock"), "");
fs.writeFileSync(path.join(attempt5A, "home", "oauth-token.json"), "renewed-secret-token");
fs.writeFileSync(path.join(attempt5A, "outbox", "result-1.json"), JSON.stringify({ status: "done", summary: "ok" }));
const ctrl5A = acquireRunControl(attempt5A, { holder: buildRunControlHolder("sup:1"), purpose: "dispatch" });
const token5APath = path.join(attempt5A, "sup-token.json");
fs.writeFileSync(token5APath, JSON.stringify({ controlEpoch: ctrl5A.controlEpoch, controlToken: ctrl5A.controlToken }));
fs.writeFileSync(path.join(attempt5A, "receipt.json"), JSON.stringify({
  by: "supervisor", kind: "exited", workerResultPresent: true
}));

// Supervisor runs p4-settle.mjs, then crashes before running the release/finalize-home step
execFileSync(process.execPath, [path.join(v3BundleDir, "p4-settle.mjs"), attempt5A, token5APath]);
const resultExistsBeforeAdopt = fs.existsSync(path.join(attempt5A, "result.json"));

// Now run p4-adopt.mjs (from v3 probe bundle)
const adopt5AOut = JSON.parse(
  execFileSync(process.execPath, [path.join(v3BundleDir, "p4-adopt.mjs"), attempt5A], { encoding: "utf8" })
);
const privateHomeStillLeakedOnDisk = fs.existsSync(path.join(attempt5A, "home", "oauth-token.json"));

// Sub-probe 5B: Reaper (§9.8) holds attempt.lock on a dead attempt while cleaning home ->
// concurrent p4-adopt.mjs (§9.7) misclassifies the dead attempt as "attempt-lock-held" (running)!
const attempt5B = path.join(tmpRoot, "attempt-5B");
fs.mkdirSync(path.join(attempt5B, "home"), { recursive: true });
fs.writeFileSync(path.join(attempt5B, "attempt.lock"), "");

const reaperProc = spawn("python3", ["-c", `
import fcntl, os, sys, time
fd = os.open(sys.argv[1], os.O_RDWR)
fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
print("locked", flush=True)
time.sleep(5)
`, path.join(attempt5B, "attempt.lock")], { stdio: ["ignore", "pipe", "inherit"] });

await new Promise((resolve) => {
  reaperProc.stdout.on("data", (d) => {
    if (d.toString().includes("locked")) resolve();
  });
});

const adoptDuringReaperOut = JSON.parse(
  execFileSync(process.execPath, [path.join(v3BundleDir, "p4-adopt.mjs"), attempt5B], { encoding: "utf8" })
);
reaperProc.kill("SIGKILL");

// Sub-probe 5C: "terminal" mode (interactive REPL agent that writes outbox/result-1.json and waits for
// supervisor exit command). Supervisor dies -> agent stays alive in pane until gate hardCeilingMs ->
// gate kills with stoppedBy="hard-ceiling" -> adopt settles as status="timeout", losing completed result!
const attempt5C = path.join(tmpRoot, "attempt-5C");
fs.mkdirSync(path.join(attempt5C, "outbox"), { recursive: true });
fs.writeFileSync(path.join(attempt5C, "attempt.lock"), "");
const replWorkerScript = path.join(attempt5C, "repl-worker.py");
fs.writeFileSync(replWorkerScript, `
import json, os, sys, time
outbox = os.path.join(sys.argv[1], "outbox", "result-1.json")
with open(outbox, "w") as f:
    json.dump({"contract": {"id": "agent-result-claim", "version": 2}, "status": "done", "summary": "completed work"}, f)
time.sleep(10)
`);

execFileSync("python3", ["-c", `
import fcntl, os, subprocess, sys
d = sys.argv[1]
lock_fd = os.open(os.path.join(d, "attempt.lock"), os.O_RDWR)
fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
os.set_inheritable(lock_fd, True)
subprocess.run([
    "python3", sys.argv[2],
    "--fd", str(lock_fd),
    "--ceiling-ms", "200",
    "--report", os.path.join(d, "gate-exit.json"),
    "--stdout", os.path.join(d, "stdout.log"),
    "--stderr", os.path.join(d, "stderr.log"),
    "--", "python3", sys.argv[3], d
