const outboxClaim5C = JSON.parse(fs.readFileSync(path.join(attempt5C, "outbox", "result-1.json"), "utf8"));
const settledResult5C = JSON.parse(fs.readFileSync(path.join(attempt5C, "result.json"), "utf8"));
const receipt5C = JSON.parse(fs.readFileSync(path.join(attempt5C, "receipt.json"), "utf8"));

// Sub-probe 5D:
// (1) 2-level grandchild (gate -> worker -> C1 (ignores SIGTERM) -> C2) escapes p4_gate.py single-pass subreaper loop
// (2) Worker that ignores SIGTERM hangs p4_gate.py past hardCeilingMs because gate main loop only sends SIGTERM
const attempt5D = path.join(tmpRoot, "attempt-5D");
fs.mkdirSync(attempt5D, { recursive: true });
fs.writeFileSync(path.join(attempt5D, "attempt.lock"), "");
const grandchildPidFile = path.join(attempt5D, "grandchild.pid");
